insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_math_v1'
from (values
('111.28.b.2.A',2,'Which set of numbers includes both rational and irrational numbers?','["real numbers", "whole numbers", "integers", "natural numbers"]'::jsonb,0,'The real numbers are made of the rational and irrational numbers together.','original'),
('111.28.b.2.A',3,'Which number is irrational?','["0.75", "√7", "√49", "−3"]'::jsonb,1,'√7 is a non-terminating, non-repeating decimal; √49 = 7.','original'),
('111.28.b.2.A',3,'Which number is rational?','["√3", "π", "0.333…", "√11"]'::jsonb,2,'A repeating decimal equals 1/3, a ratio of integers.','original'),
('111.28.b.2.A',4,'Where does −4 belong in a diagram of the real number system?','["whole numbers only", "natural numbers", "irrational numbers", "integers, rational numbers and real numbers"]'::jsonb,3,'Negative integers are integers, so they are rational and real, but not whole.','original'),
('111.28.b.2.A',4,'A decimal that never ends and never repeats is...','["irrational", "rational", "an integer", "a whole number"]'::jsonb,0,'Only rational numbers have terminating or repeating decimals.','original'),
('111.28.b.2.A',3,'Which set is a subset of the rational numbers?','["numbers that are not real", "the integers", "numbers like π and √2", "the irrational numbers"]'::jsonb,1,'Every integer is a rational number.','original'),
('111.28.b.2.A',4,'Which number is a whole number, an integer, and a rational number?','["12.5", "√12", "12", "−12"]'::jsonb,2,'12 is not negative or fractional, so it is in all three sets.','original'),
('111.28.b.2.B',3,'Between which two integers is √20?','["5 and 6", "10 and 11", "3 and 4", "4 and 5"]'::jsonb,3,'4² = 16 and 5² = 25, so √20 is between 4 and 5.','original'),
('111.28.b.2.B',3,'Between which two integers is √50?','["7 and 8", "6 and 7", "8 and 9", "25 and 26"]'::jsonb,0,'49 < 50 < 64.','original'),
('111.28.b.2.B',3,'Between which two integers is √90?','["45 and 46", "9 and 10", "10 and 11", "8 and 9"]'::jsonb,1,'81 < 90 < 100.','original'),
('111.28.b.2.B',4,'Which is the best estimate of √30 to the nearest tenth?','["5.0", "5.9", "5.5", "6.0"]'::jsonb,2,'5.5² = 30.25, which is very close to 30.','original'),
('111.28.b.2.B',4,'Which is the best estimate of √10 to the nearest tenth?','["3.5", "3.9", "3.0", "3.2"]'::jsonb,3,'3.2² = 10.24 and 3.1² = 9.61; 3.2 is closer.','original'),
('111.28.b.2.B',3,'Which is the closest to the value of π as a fraction?','["22/7", "7/22", "31/10", "3/4"]'::jsonb,0,'22/7 ≈ 3.1429.','original'),
('111.28.b.2.B',4,'Which point on a number line is the best placement for √15?','["exactly 3", "just below 4", "just above 4", "exactly 4"]'::jsonb,1,'√15 ≈ 3.87 since 3.9² ≈ 15.2.','original'),
('111.28.b.2.B',4,'Which is closest to π² ?','["3.1", "12.6", "9.9", "6.3"]'::jsonb,2,'3.14² ≈ 9.86.','original'),
('111.28.b.2.B',3,'Which number is closest to √2?','["1.8", "2.0", "1.2", "1.4"]'::jsonb,3,'1.4² = 1.96.','original'),
('111.28.b.2.B',3,'Which is between 6 and 7?','["√40", "√50", "√30", "√20"]'::jsonb,0,'36 < 40 < 49.','original'),
('111.28.b.2.B',3,'Which is between 2 and 3?','["√16", "√7", "√10", "√3"]'::jsonb,1,'4 < 7 < 9.','original'),
('111.28.b.2.C',3,'Write 630,000,000 in scientific notation.','["6.3 × 10⁷", "6.3 × 10⁹", "6.3 × 10⁸", "63.0 × 10⁸"]'::jsonb,2,'Place the decimal after the first digit; that is 8 places, so 6.3 × 10⁸.','original'),
('111.28.b.2.C',3,'Write 7,900,000 in scientific notation.','["7.9 × 10⁵", "79.0 × 10⁶", "7.9 × 10⁷", "7.9 × 10⁶"]'::jsonb,3,'Place the decimal after the first digit; that is 6 places, so 7.9 × 10⁶.','original'),
('111.28.b.2.C',3,'Write 7,900 in scientific notation.','["7.9 × 10³", "7.9 × 10⁴", "7.9 × 10²", "79.0 × 10³"]'::jsonb,0,'Place the decimal after the first digit; that is 3 places, so 7.9 × 10³.','original'),
('111.28.b.2.C',3,'Write 240,000,000 in scientific notation.','["2.4 × 10⁷", "2.4 × 10⁸", "24.0 × 10⁸", "2.4 × 10⁹"]'::jsonb,1,'Place the decimal after the first digit; that is 8 places, so 2.4 × 10⁸.','original'),
('111.28.b.2.C',4,'Write 0.000054 in scientific notation.','["5.4 × 10⁵", "5.4 × 10⁻⁶", "5.4 × 10⁻⁵", "5.4 × 10⁻⁴"]'::jsonb,2,'Move the decimal 5 places right to get 5.4, so the exponent is −5.','original'),
('111.28.b.2.C',4,'Write 0.0091 in scientific notation.','["9.1 × 10³", "9.1 × 10⁻⁴", "9.1 × 10⁻²", "9.1 × 10⁻³"]'::jsonb,3,'Move the decimal 3 places right to get 9.1, so the exponent is −3.','original'),
('111.28.b.2.C',4,'Write 0.0068 in scientific notation.','["6.8 × 10⁻³", "6.8 × 10⁻²", "6.8 × 10³", "6.8 × 10⁻⁴"]'::jsonb,0,'Move the decimal 3 places right to get 6.8, so the exponent is −3.','original'),
('111.28.b.2.C',4,'Write 0.00036 in scientific notation.','["3.6 × 10⁻⁵", "3.6 × 10⁻⁴", "3.6 × 10⁴", "3.6 × 10⁻³"]'::jsonb,1,'Move the decimal 4 places right to get 3.6, so the exponent is −4.','original'),
('111.28.b.2.C',3,'Which is 4.5 × 10⁻³ in standard form?','["0.045", "4500", "0.0045", "0.00045"]'::jsonb,2,'A negative exponent moves the decimal left 3 places.','original'),
('111.28.b.2.C',3,'Which number is written in scientific notation?','["320 × 10³", "32 × 10⁴", "0.32 × 10⁶", "3.2 × 10⁵"]'::jsonb,3,'The first factor must be at least 1 and less than 10.','original'),
('111.28.b.2.C',4,'The distance from Earth to the Sun is about 93,000,000 miles. Which shows this in scientific notation?','["9.3 × 10⁷", "93 × 10⁶", "9.3 × 10⁸", "9.3 × 10⁶"]'::jsonb,0,'Eight digits means 7 places after the first digit.','original'),
('111.28.b.2.C',4,'A cell is about 0.000012 meters wide. Which is its width in scientific notation?','["12 × 10⁻⁶", "1.2 × 10⁻⁵", "1.2 × 10⁻⁶", "1.2 × 10⁵"]'::jsonb,1,'The decimal moves 5 places to the right.','original'),
('111.28.b.2.D',3,'Which number is greatest?','["4", "15/4", "√17", "3.9"]'::jsonb,2,'√17 ≈ 4.12.','original'),
('111.28.b.2.D',3,'Which number is least?','["−π", "−3.1", "−3", "−√10"]'::jsonb,3,'−√10 ≈ −3.16, which is farther left than −π ≈ −3.14.','original'),
('111.28.b.2.D',3,'Which is between 3 and 4?','["√11", "√20", "√5", "√16"]'::jsonb,0,'9 < 11 < 16.','original'),
('111.28.b.2.D',4,'A scientist compares 4.2 × 10³, 3.9 × 10⁴ and 5 × 10². Which is the greatest value in standard form?','["4,200", "39,000", "500", "3,900"]'::jsonb,1,'3.9 × 10⁴ = 39,000, which is larger than 4,200 and 500.','original'),
('111.28.b.2.D',4,'Which list is in order from greatest to least?','["π, 22/7, 3.1", "3.1, 22/7, π", "22/7, π, 3.1", "3.1, π, 22/7"]'::jsonb,2,'22/7 ≈ 3.1429, π ≈ 3.1416, and 3.1 is smallest.','original'),
('111.28.b.2.D',4,'Which is greater, 2/3 or √0.36?','["√0.36", "They cannot be compared", "They are equal", "2/3"]'::jsonb,3,'√0.36 = 0.6 and 2/3 ≈ 0.667.','original'),
('111.28.b.3.A',3,'A triangle is dilated by a scale factor of 3. A side of 4 becomes...','["12", "1", "4/3", "7"]'::jsonb,0,'4 × 3 = 12.','original'),
('111.28.b.3.A',3,'Two similar rectangles have sides 2 by 5 and 6 by x. What is x?','["13", "15", "3", "10"]'::jsonb,1,'The scale factor is 3, so x = 5 × 3.','original'),
('111.28.b.3.A',4,'Triangle ABC is similar to triangle DEF. AB = 6, DE = 9 and BC = 8. What is EF?','["9", "11", "12", "10"]'::jsonb,2,'The scale factor is 9/6 = 1.5, and 8 × 1.5 = 12.','original'),
('111.28.b.3.A',3,'In a dilation, corresponding angles are...','["always right angles", "doubled", "halved", "congruent"]'::jsonb,3,'A dilation changes size, not angle measure.','original'),
('111.28.b.3.A',4,'A photo is 4 in. by 6 in. It is enlarged so its short side is 10 in. How long is the long side?','["15 in.", "14 in.", "16 in.", "12 in."]'::jsonb,0,'The scale factor is 2.5, so 6 × 2.5 = 15.','original'),
('111.28.b.3.A',4,'The ratio of corresponding sides of two similar triangles is 2:5. If a side of the small triangle is 8, the matching side of the large triangle is...','["13", "20", "3.2", "10"]'::jsonb,1,'8 ÷ 2 × 5 = 20.','original'),
('111.28.b.3.A',3,'A scale factor of 1/2 produces a figure that is...','["turned upside down", "larger than the original", "smaller than the original", "the same size"]'::jsonb,2,'A factor less than 1 shrinks the figure.','original'),
('111.28.b.3.A',4,'A map uses a scale of 1 cm : 20 km. Two cities are 6 cm apart on the map. What is the real distance?','["3.3 km", "26 km", "12 km", "120 km"]'::jsonb,3,'6 × 20 = 120.','original'),
('111.28.b.3.B',3,'The point (2, 3) is dilated from the origin by a scale factor of 2. What are the new coordinates?','["(4, 6)", "(2, 6)", "(4, 3)", "(1, 1.5)"]'::jsonb,0,'Multiply both coordinates by 2.','original'),
('111.28.b.3.B',3,'The point (6, 9) is dilated from the origin by a scale factor of 1/3. What are the new coordinates?','["(18, 27)", "(2, 3)", "(3, 6)", "(2, 9)"]'::jsonb,1,'Multiply both coordinates by 1/3.','original'),
('111.28.b.3.B',4,'A triangle with vertices (1, 1), (3, 1), (1, 4) is dilated by a factor of 2 from the origin. What is the image of (3, 1)?','["(6, 1)", "(5, 1)", "(6, 2)", "(3, 2)"]'::jsonb,2,'(3×2, 1×2) = (6, 2).','original'),
('111.28.b.3.B',4,'After a dilation from the origin, which attribute of a shape is the same?','["its perimeter", "its side lengths", "its area", "its angle measures"]'::jsonb,3,'Dilations keep shape (angles) but change size unless the factor is 1.','original'),
('111.28.b.3.B',4,'A rectangle has vertices (0, 0), (4, 0), (4, 2), (0, 2). It is dilated by a factor of 3 from the origin. What is the new area?','["72", "36", "8", "24"]'::jsonb,0,'The new rectangle is 12 by 6, so the area is 72.','original'),
('111.28.b.3.B',3,'A dilation with a scale factor greater than 1 is called an...','["translation", "enlargement", "reduction", "reflection"]'::jsonb,1,'Factors above 1 make the figure larger.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_math_v1'
from (values
('111.28.b.3.B',4,'How do the side lengths of a figure and its dilation by 3 compare?','["They are the same", "Each side is 1/3 as long", "Each side of the image is 3 times as long", "Each side is 3 units longer"]'::jsonb,2,'Dilation multiplies lengths by the scale factor.','original'),
('111.28.b.3.C',3,'Which rule describes a dilation by a scale factor of 4 from the origin?','["(x, y) → (x + 4, y + 4)", "(x, y) → (x/4, y/4)", "(x, y) → (4x, y)", "(x, y) → (4x, 4y)"]'::jsonb,3,'Every coordinate is multiplied by 4.','original'),
('111.28.b.3.C',3,'Which rule describes a dilation by a scale factor of 1/2 from the origin?','["(x, y) → (x/2, y/2)", "(x, y) → (x − 2, y − 2)", "(x, y) → (2x, 2y)", "(x, y) → (x/2, y)"]'::jsonb,0,'Every coordinate is multiplied by 1/2.','original'),
('111.28.b.3.C',4,'A point (8, −4) is dilated by (x, y) → (1.5x, 1.5y). What is the image?','["(8, −6)", "(12, −6)", "(9.5, −2.5)", "(12, −4)"]'::jsonb,1,'1.5 × 8 = 12 and 1.5 × (−4) = −6.','original'),
('111.28.b.3.C',4,'The rule (x, y) → (2.5x, 2.5y) is applied. What is the image of (4, 6)?','["(1.6, 2.4)", "(6.5, 8.5)", "(10, 15)", "(10, 6)"]'::jsonb,2,'2.5 × 4 = 10 and 2.5 × 6 = 15.','original'),
('111.28.b.3.C',4,'Which scale factor takes (6, 10) to (3, 5)?','["−1", "3", "2", "1/2"]'::jsonb,3,'3/6 = 5/10 = 1/2.','original'),
('111.28.b.3.C',4,'Which scale factor takes (2, 5) to (6, 15)?','["3", "10", "4", "1/3"]'::jsonb,0,'6/2 = 15/5 = 3.','original'),
('111.28.b.3.C',3,'A scale factor of 1 creates a figure that is...','["smaller", "congruent to the original", "larger", "reflected"]'::jsonb,1,'Multiplying by 1 changes nothing.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (3, −3) and (5, 1)?','["6", "−2", "2", "1/2"]'::jsonb,2,'Slope = rise ÷ run = 4/2 = 2.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (−3, 2) and (1, −6)?','["−1/2", "−4", "2", "−2"]'::jsonb,3,'Slope = rise ÷ run = −8/4 = −2.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (−2, 1) and (0, 4)?','["3/2", "2/3", "5", "−3/2"]'::jsonb,0,'Slope = rise ÷ run = 3/2.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (3, −3) and (6, −12)?','["−6", "−3", "3", "−1/3"]'::jsonb,1,'Slope = rise ÷ run = −9/3 = −3.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (−1, −1) and (0, 1)?','["−2", "1/2", "2", "3"]'::jsonb,2,'Slope = rise ÷ run = 2/1 = 2.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (−3, −1) and (1, 5)?','["10", "2/3", "−3/2", "3/2"]'::jsonb,3,'Slope = rise ÷ run = 6/4 = 3/2.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (3, −3) and (7, −11)?','["−2", "2", "−1/2", "−4"]'::jsonb,0,'Slope = rise ÷ run = −8/4 = −2.','original'),
('111.28.b.4.A',4,'What is the slope of the line through (3, 0) and (4, −2)?','["−1", "−2", "−1/2", "2"]'::jsonb,1,'Slope = rise ÷ run = −2/1 = −2.','original'),
('111.28.b.4.A',3,'Slope is the ratio of which two changes?','["y minus x", "the change in x to the change in y", "the change in y to the change in x", "x added to y"]'::jsonb,2,'Slope = rise over run.','original'),
('111.28.b.4.A',3,'A line goes up 6 units for every 3 units to the right. What is its slope?','["3", "18", "1/2", "2"]'::jsonb,3,'6/3 = 2.','original'),
('111.28.b.4.A',4,'A line goes down 4 units for every 8 units to the right. What is its slope?','["−1/2", "2", "−2", "1/2"]'::jsonb,0,'−4/8 = −1/2.','original'),
('111.28.b.4.A',3,'A horizontal line has a slope of...','["1", "0", "−1", "undefined"]'::jsonb,1,'There is no vertical change.','original'),
('111.28.b.4.A',4,'A vertical line has a slope that is...','["positive", "0", "undefined", "1"]'::jsonb,2,'The run is 0, and you cannot divide by 0.','original'),
('111.28.b.4.A',4,'Why can any two points on a line be used to find its slope?','["the line must go through the origin", "the slope changes between points", "only the first two points work", "similar right triangles drawn along the line have the same ratio of rise to run"]'::jsonb,3,'All the slope triangles are similar, so rise/run is constant.','original'),
('111.28.b.4.B',3,'A line through the origin passes through (4, 12). What is its unit rate (slope)?','["3", "1/3", "16", "8"]'::jsonb,0,'12 ÷ 4 = 3.','original'),
('111.28.b.4.B',3,'A proportional relationship is graphed as...','["a horizontal line at y = 1", "a straight line through the origin", "a curve", "a line that crosses the y-axis at 5"]'::jsonb,1,'y = kx passes through (0, 0).','original'),
('111.28.b.4.B',4,'A car travels 150 miles in 3 hours at a steady rate. What is the slope of the line of distance versus time?','["450 miles per hour", "3 miles per hour", "50 miles per hour", "153 miles per hour"]'::jsonb,2,'150 ÷ 3 = 50.','original'),
('111.28.b.4.B',4,'A graph of cost versus pounds goes through (0, 0) and (5, 20). What does the slope represent?','["the starting fee", "the total cost", "the number of pounds", "the price of one pound"]'::jsonb,3,'20 ÷ 5 = 4 dollars per pound.','original'),
('111.28.b.4.B',3,'Which equation has a graph that passes through the origin?','["y = 6x", "y = x − 6", "y = 6x + 1", "y = 6"]'::jsonb,0,'y = kx always contains (0, 0).','original'),
('111.28.b.4.B',4,'A graph of y = 2.5x passes through which point?','["(4, 6.5)", "(4, 10)", "(2.5, 4)", "(4, 8)"]'::jsonb,1,'2.5 × 4 = 10.','original'),
('111.28.b.4.C',3,'A table shows x = 0, 1, 2, 3 and y = 5, 8, 11, 14. What is the y-intercept?','["3", "14", "5", "8"]'::jsonb,2,'When x = 0, y = 5.','original'),
('111.28.b.4.C',3,'A table shows x = 0, 1, 2, 3 and y = 9, 11, 13, 15. What is the y-intercept?','["15", "11", "2", "9"]'::jsonb,3,'When x = 0, y = 9.','original'),
('111.28.b.4.C',3,'A table shows x = 0, 1, 2, 3 and y = 9, 13, 17, 21. What is the y-intercept?','["9", "13", "4", "21"]'::jsonb,0,'When x = 0, y = 9.','original'),
('111.28.b.4.C',3,'A table shows x = 0, 1, 2, 3 and y = 7, 11, 15, 19. What is the y-intercept?','["19", "7", "4", "11"]'::jsonb,1,'When x = 0, y = 7.','original'),
('111.28.b.4.C',4,'A table shows x = 0, 2, 4, 6 and y = 8, 12, 16, 20. What is the rate of change?','["4", "10", "2", "8"]'::jsonb,2,'y rises 4 when x rises 2, so the rate is 2.','original'),
('111.28.b.4.C',4,'A table shows x = 0, 2, 4, 6 and y = 7, 17, 27, 37. What is the rate of change?','["10", "12", "7", "5"]'::jsonb,3,'y rises 10 when x rises 2, so the rate is 5.','original'),
('111.28.b.4.C',4,'A table shows x = 0, 2, 4, 6 and y = 3, 17, 31, 45. What is the rate of change?','["7", "14", "3", "10"]'::jsonb,0,'y rises 14 when x rises 2, so the rate is 7.','original'),
('111.28.b.4.C',4,'A table shows x = 0, 2, 4, 6 and y = 9, 21, 33, 45. What is the rate of change?','["15", "6", "12", "9"]'::jsonb,1,'y rises 12 when x rises 2, so the rate is 6.','original'),
('111.28.b.4.C',4,'A plumber charges a flat fee plus an hourly rate. The graph passes through (0, 40) and (2, 100). What is the hourly rate?','["$20", "$40", "$30", "$60"]'::jsonb,2,'(100 − 40) ÷ 2 = 30.','original'),
('111.28.b.4.C',4,'In the same situation, a graph passes through (0, 40) and (2, 100). What does the y-intercept mean?','["the hourly rate", "the number of hours", "the total after 2 hours", "the flat fee of $40"]'::jsonb,3,'At 0 hours the cost is just the fee.','original'),
('111.28.b.4.C',4,'A water tank has 50 gallons and loses 5 gallons each minute. What is the rate of change?','["−5 gallons per minute", "50 gallons per minute", "5 gallons per minute", "−50 gallons per minute"]'::jsonb,0,'The amount decreases by 5 each minute.','original'),
('111.28.b.4.C',3,'A graph crosses the y-axis at (0, −2). The y-intercept is...','["2", "−2", "0", "−2 for x"]'::jsonb,1,'The y-intercept is the y-value where x = 0.','original'),
('111.28.b.5.A',3,'Notebooks cost $2 each. Which equation gives the cost y of x notebooks?','["y = 4x", "y = x + 2", "y = 2x", "y = x/2"]'::jsonb,2,'Each notebook costs $2, so y = 2x.','original'),
('111.28.b.5.A',3,'A table shows x = 1, 2, 3 and y = 7, 14, 21. Which equation fits?','["y = 21x", "y = x + 6", "y = 7 + x", "y = 7x"]'::jsonb,3,'y is always 7 times x.','original'),
('111.28.b.5.A',4,'A runner covers 12 miles in 2 hours at a constant rate. Which equation gives distance d in t hours?','["d = 6t", "d = 2t", "d = t + 10", "d = 12t"]'::jsonb,0,'12 ÷ 2 = 6 miles per hour.','original'),
('111.28.b.5.A',4,'The line y = kx passes through (5, 20). What is k?','["1/4", "4", "15", "100"]'::jsonb,1,'20 ÷ 5 = 4.','original'),
('111.28.b.5.A',3,'Which table shows a proportional relationship y = kx?','["x: 1, 2, 3 and y: 5, 6, 7", "x: 1, 2, 3 and y: 6, 11, 16", "x: 1, 2, 3 and y: 5, 10, 15", "x: 1, 2, 3 and y: 4, 6, 8"]'::jsonb,2,'The ratio y/x is always 5.','original'),
('111.28.b.5.A',4,'A recipe uses 3 cups of flour for every 2 batches. Which equation gives flour f for b batches?','["f = b + 1", "f = 3b", "f = 2b", "f = 1.5b"]'::jsonb,3,'3 ÷ 2 = 1.5 cups per batch.','original'),
('111.28.b.5.B',3,'A gym costs $25 to join and $10 per month. Which equation gives the total cost y after x months?','["y = 10x + 25", "y = 25x + 10", "y = 35x", "y = 10x − 25"]'::jsonb,0,'$10 per month plus a $25 fee.','original'),
('111.28.b.5.B',3,'A table shows x = 0, 1, 2 and y = 4, 7, 10. Which equation fits?','["y = 4x + 3", "y = 3x + 4", "y = 3x", "y = x + 4"]'::jsonb,1,'The slope is 3 and the y-intercept is 4.','original'),
('111.28.b.5.B',4,'A line has slope −2 and passes through (0, 6). Which is its equation?','["y = 2x + 6", "y = −2x − 6", "y = −2x + 6", "y = 6x − 2"]'::jsonb,2,'m = −2 and b = 6.','original'),
('111.28.b.5.B',4,'A taxi charges $3 plus $2 per mile. What is the cost of a 7-mile ride?','["$21", "$14", "$23", "$17"]'::jsonb,3,'y = 2(7) + 3 = 17.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
